import React, { useEffect, useState } from "react";
import axios from "axios";

import Sidebar from "../components/Sidebar";
import PostCard from "../components/PostCard";
import CreatePostModal from "../components/CreatePostModal";
import ImageModal from "../components/ImageModal";

import "../styles/main.css";

export default function Feed({ user }) {

  const [posts, setPosts] = useState([]);
  const [showModal, setShowModal] = useState(false);
  const [selectedPost, setSelectedPost] = useState(null);
  const [showWelcome, setShowWelcome] = useState(false);

  // 🔥 Obtener posts
  const getPosts = () => {
    axios.get("http://localhost:5000/api/posts")
      .then(res => setPosts(res.data))
      .catch(err => console.error(err));
  };

useEffect(() => {
  getPosts();

  const first = localStorage.getItem("firstLogin");

  if (first === "true") {
    setShowWelcome(true);
    localStorage.removeItem("firstLogin"); // 🔥 para que no vuelva a salir
  }

}, []);
return (
  <div className="layout">

    {/* IZQUIERDA */}
    <Sidebar 
      user={user} 
      openModal={() => setShowModal(true)} 
    />

    {/* CENTRO */}
    <div className="feed">
      {posts.map((post, index) => (
        <PostCard 
          key={index} 
          post={post} 
          onImageClick={() => setSelectedPost(post)}
        />
      ))}
    </div>

    {/* DERECHA */}
<div className="rightbar">

  <h3>Sobre nosotros</h3>

  <div className="info-item" onClick={() => setInfoModal("about")}>
    👥 Quiénes somos
  </div>

  <div className="info-item" onClick={() => setInfoModal("mission")}>
    🎯 Nuestra misión
  </div>

  <div className="info-item" onClick={() => setInfoModal("projects")}>
    🚀 Proyectos
  </div>

</div>

    {/* MODAL CREAR POST */}
    {showModal && (
      <CreatePostModal 
        close={() => setShowModal(false)} 
        refreshPosts={getPosts}
        user={user}
      />
    )}

    {/* MODAL IMAGEN */}
    {selectedPost && (
      <ImageModal 
        post={selectedPost}
        close={() => setSelectedPost(null)}
      />
    )}

    {/* 🔥 MODAL BIENVENIDA (AQUÍ VA) */}
    {showWelcome && (
      <div className="modal">
        <div className="welcome-modal">

          <h2>Bienvenido 🎉</h2>
          <p>Ya puedes comenzar a compartir tus momentos 💜</p>

          <button onClick={() => setShowWelcome(false)}>
            Empezar
          </button>

        </div>
      </div>
    )}

  </div>
);

}
